    "incenseHa": "Turaren Luban da Za'afaran",
    "descriptionFr": "Dans la tradition mystique d'Al-Buni (Shams al-Ma'arif), le Nom Très Saint الرَّحْمَنُ (Ar-Rahmān) possède un poids Abjad de 298. Il est utilisé pour attirer le tout-miséricordieux et purifier l'esprit.",
    "descriptionEn": "In Al-Buni's mystical tradition (Shams al-Ma'arif), the Most Holy Name الرَّحْمَنُ (Ar-Rahmān) possesses an Abjad weight of 298. It is utilized to attract the all-merciful and purify the spirit.",
    "descriptionHa": "A cikin littafin sirri na Al-Buni (Shams al-Ma'arif), Sifa ta Allah الرَّحْمَنُ (Ar-Rahmān) tana dauke da nauyin Abjad 298. An fi amfani da ita don samun Mai Rahama Baki Daya da tsarkake zuciya.",
    "invocationAr": "يَا الرَّحْمَنُ أَسْأَلُكَ بِسِرِّ اسْمِكَ العَظِيمِ أَنْ تَمُنَّ عَلَيَّ بِبَرَكَاتِكَ وَأَنْ تَكْفِيَنِي مَا أَهَمَّنِي",
    "invocationPhonetic": "Ya Ar-Rahmān as'aluka bi-sirri ismika al-'adimi an tamunna 'alayya bi-barakatika wa an takfiyani ma ahammani",
    "invocationFr": "Ô Ar-Rahmān, je Te demande par le secret de Ton Nom Sublime de m'accorder Tes bénédictions et de me suffire contre ce qui me préoccupe !",
    "invocationEn": "O Ar-Rahmān, I ask You by the secret of Your Supreme Name to bestow Your blessings upon me and suffice me against all worries!",
    "invocationHa": "Ya Allah Ar-Rahmān, ina rokonka da sirrin Sunanka Mai Girma ka ba ni albarkarka ka kuma kaye min dukkan damuwata!",
    "stepsFr": [
      "Accomplir une ablution complète (Taharat) et se tourner vers la Qibla.",
      "Réciter Yā Ar-Rahmān au nombre exact de son poids Abjad (298 fois).",
      "Tracer le carré magique 3x3 correspondant avec de l'encre de safran et d'eau de rose.",
      "Conclure par la prière sur le Prophète (Salawat) et faire ses invocations."
    ],
    "stepsEn": [
      "Perform complete ablution (Taharat) and face the Qibla.",
      "Recite Yā Ar-Rahmān according to its exact Abjad weight (298 times).",
      "Draw the corresponding 3x3 square with saffron and rosewater ink.",
      "Conclude with Salawat upon the Prophet and make your supplications."
    ],
    "stepsHa": [
      "Gudanar da cikakkiyar alwala (Taharat) sannan ka fuskanci Alkibla.",
      "Karanta Yā Ar-Rahmān gwargwadon ainihin nauyin Abjad (298 sau).",
      "Rubuta siffar Wafq 3x3 dace da tawadar za'afaran da ruwan wardi.",
      "Kammala da Salatin Annabi sannan ka roƙi buƙatunka."
    ]
