  "invocationAr": "رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكاً لاَّ يَنبَغِي لأَحَدٍ مِّن بَعْدِي إِنَّكَ أَنتَ الْوَهَّابُ. اَللَّهُمَّ سَخِّرْ لِي الْأَرْزَاقَ وَالْقُلُوبَ",
  "invocationPhonetic": "Rabbi ighfir li wa hab li mulkan la yanbaghi li-ahadin min ba'di innaka Anta al-Wahhab. Allahumma sakhkhir li al-arzaqa wal-qulub",
  "invocationFr": "Seigneur, pardonne-moi et accorde-moi un royaume tel qu'il ne conviendra à personne après moi, car c'est Toi le Grand Donateur ! Ô Allah, soumets-moi les subsistances et les cœurs !",
  "invocationEn": "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower! O Allah, subject to me provisions and hearts!",
