    "Cin burodin garin sha'ir, dabino, ruwa mai kyau da busassun 'ya'yan itace.",
    "Gudanar da ambaton 'Ya Quddus' ko 'Ya Latif' babu kewa.",
    "Kauce wa maganganun banza da kare tsarkin zuciya."
