  "invocationAr": "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَاللَّهُمَّ أَصْلِحْ نِيَّتِي وَسَرِيرَتِي",
