  "invocationEn": "Our Lord, judge between us and our people in truth, for You are the best of judges! O Opener, open for me every goodness!",
  "invocationHa": "Ubangijinmu, ka yi hukunci a tsakaninmu da mutanenmu da gaskiya, Kai ne mafi alherin masu hukunci! Ya Mai Bude Kofofi, ka bude mini kowace kofar alheri!",
