  "invocationAr": "أَقْسَمْتُ عَلَيْكَ يَا ظَلَمْيَاءِيلُ بِسِرِّ حَرْفِ ظ وَبِاسْمِ اللَّهِ العَظِيمِ أَنْ تُمِدَّنِي بِالتَّوْفِيقِ وَالحِفْظِ",
  "invocationPhonetic": "Aqsaktu 'alayka ya ظَلَمْيَاءِيلُ bi-sirri harfi ظ wa bi-ismillahi al-'Azimi an tumiddani bit-tawfiqi wal-hifz",
  "invocationFr": "Je t'adjure, ô Zayail, par le secret de la lettre ظ et par le Grand Nom d'Allah, de m'accorder la réussite et la protection.",
  "invocationEn": "I adjure you, O Zayail, by the secret of the letter ظ and by the Supreme Name of Allah, to support me with success and protection.",
  "invocationHa": "Ina rantse maka ya Zayail albarkacin sirrin harfin ظ da sunan Allah Mai Girma ka tallafa min da daukaka da kariya.",
